import heapq
from collections import deque

def safest_walk(grid):
    rows, cols = len(grid), len(grid[0])
    cover = [[-1] * cols for _ in range(rows)]
    queue = deque()
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'G':
                cover[i][j] = 0
                queue.append((i, j))
    while queue:
        i, j = queue.popleft()
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < rows and 0 <= b < cols and cover[a][b] < 0:
                cover[a][b] = cover[i][j] + 1
                queue.append((a, b))
    best = [[-1] * cols for _ in range(rows)]
    best[0][0] = cover[0][0]
    heap = [(-cover[0][0], 0, 0)]
    while heap:
        s, i, j = heapq.heappop(heap)
        s = -s
        if s < best[i][j]:
            continue
        if (i, j) == (rows - 1, cols - 1):
            return s
        for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= a < rows and 0 <= b < cols and grid[a][b] != '#':
                t = min(s, cover[a][b])
                if t > best[a][b]:
                    best[a][b] = t
                    heapq.heappush(heap, (-t, a, b))
    return -1

