from collections import deque

def safest_walk(grid):
    rows, cols = len(grid), len(grid[0])
    cams = [(i, j) for i in range(rows) for j in range(cols) if grid[i][j] == 'G']
    far = [[min(abs(i - a) + abs(j - b) for a, b in cams) for j in range(cols)] for i in range(rows)]
    for level in range(far[0][0], -1, -1):
        seen = {(0, 0)}
        queue = deque([(0, 0)])
        while queue:
            i, j = queue.popleft()
            if (i, j) == (rows - 1, cols - 1):
                return level
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < rows and 0 <= b < cols and (a, b) not in seen and grid[a][b] != '#' and far[a][b] >= level:
                    seen.add((a, b))
                    queue.append((a, b))
    return -1
